{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Laninamivir octanoate, a lipophilic long-chain ester prodrug, has only 15% oral bioavailability in humans, providing a direct sub-20% example for a highly lipophilic ester prodrug and supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat has a simulated absolute oral bioavailability of 8.6% in virtual subjects; despite structural differences, its high transfer score and sub-20% F support a low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pravastatin's absolute oral bioavailability is 17% in humans, below the 20% threshold, adding high-transfer evidence that marketed drugs can be sub-20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Hexarelin (HEX) has an oral bioavailability of only 0.3% in humans, a high-transfer sub-20% example, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DVAS, a dodecyl ester dipeptide, has 60% oral bioavailability in healthy volunteers, a contradictory example for long-chain ester prodrugs; however, its free amino group and lack of beta-lactone reduce transferability to the neutral, poorly soluble query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Chloramphenicol palmitate, a neutral long-chain ester prodrug, has ~85% oral bioavailability in children, but its very low transfer score and absence of the reactive beta-lactone make it a weak counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is orlistat, a highly lipophilic neutral beta-lactone ester designed for local gastrointestinal action. The most transferable experimental evidence (eliglustat, pravastatin, hexarelin, laninamivir octanoate) all show oral bioavailability below 20%, and the structurally relevant lipophilic ester prodrug laninamivir octanoate has F=15%. High-F long-chain ester prodrugs (DVAS, chloramphenicol palmitate) are less transferable because they lack the reactive beta-lactone and/or contain ionizable groups. Therefore, predict low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule (orlistat) is present in the evidence set.",
    "The high-F long-chain ester prodrugs (DVAS, chloramphenicol palmitate) are not fully explained by transfer scores; their structural differences (ionizable group, no beta-lactone) are inferred.",
    "The impact of the beta-lactone's reactivity and the very low aqueous solubility on absorption is not directly measured in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

